onCreate: function () {
  const context = this.getView().getModel().createEntry("/Products", {
    properties: { Name: "", Price: "0.00" }
  });
  this.getView().setBindingContext(context); // the form edits the new entry
},

onSave: function () {
  this.getView().getModel().submitChanges({
    success: function () { /* sent in one $batch */ }
  });
},

onCancel: function () {
  this.getView().getModel().resetChanges();
}

const oBinding = this.byId("table").getBinding("items");   // sap.ui.model.odata.v4.ODataListBinding

// CREATE
const oContext = oBinding.create({ Name: "New", Price: 100 });
await oContext.created();

// UPDATE - two-way binding or code writes it, then submit the update group
await oContext.setProperty("Name", "Updated");
await oModel.submitBatch("productChanges");

// DELETE
await oContext.delete();

// READ in code (normally you just bind)
