onApprove: function () {
  const orderId = this.getView().getBindingContext().getProperty("OrderID");
  this.getView().getModel().callFunction("/ApproveOrder", {
    method: "POST",
    urlParameters: { OrderID: orderId },
    success: function (result) {
      MessageToast.show("Order approved");
    },
    error: function () {
      MessageBox.error("Approval failed");
    }
  });
}

// V2: deferred, so a dialog can bind to the parameters
const oHandle = oModel.callFunction("/ApproveOrder", {
  method: "POST",
  urlParameters: { OrderID: "500000001", Comment: "" },
  groupId: "approvalGroup"                  // a deferred group
});
oHandle.contextCreated().then((oContext) => this.dialog.setBindingContext(oContext));
// user fills the dialog and presses OK:
oModel.submitChanges({ groupId: "approvalGroup" });

