const model = this.getView().getModel();
model.setDeferredGroups(model.getDeferredGroups().concat(["notes"]));

// collected, not sent yet
model.update("/Notes('1')", { Text: "Updated" }, { groupId: "notes" });
model.create("/Notes", { Text: "New" }, { groupId: "notes" });

// now both are sent in one $batch
model.submitChanges({
  groupId: "notes",
  success: function () { MessageToast.show("Notes saved"); }
});

// V2
oModel.setDeferredGroups(["productChanges"]);
oModel.setChangeGroups({
  "MyService.Product": {
    groupId: "productChanges",
    changeSetId: "changeSet1",
    single: false                // all changes in ONE change set
  }
});
// the user edits fields - nothing is sent yet
oModel.submitChanges({ groupId: "productChanges" });

// V4
const oModelV4 = new ODataModel({
  serviceUrl: "/odata/v4/products/",
  groupId: "$auto",              // reads
  updateGroupId: "productChanges" // changes wait for submitBatch
});
await oModelV4.submitBatch("productChanges");

_onOrderMatched: function (event) {
  const orderId = event.getParameter("arguments").orderId;
  this.getView().bindElement({
    path: "/Orders('" + orderId + "')",
    parameters: {
      expand: "ToItems,ToCustomer",
      select: "OrderID,Status,ToCustomer/Name,ToItems/ProductID,ToItems/Quantity"
    }
  });
  // in the view: <Table items="{ToItems}"> needs no extra request
}

// parent: element binding of the object page
this.getView().bindElement({
  path: "/OrderSet('500000001')",
  parameters: { createPreliminaryContext: true, groupId: "orderGroup" }
});

