// Component.js, init
const model = this.getModel();

model.attachMetadataFailed(function (event) {
  const response = event.getParameter("response");
  MessageBox.error("The service could not be loaded (" + response.statusCode + ").");
});

model.attachBatchRequestFailed(function () {
  MessageToast.show("A request failed");
});

_onProductMatched: function (event) {
  const id = event.getParameter("arguments").productId;
  const model = this.getView().getModel();

  model.metadataLoaded().then(function () {
    const path = model.createKey("/Products", { ProductID: id });
    this.getView().bindElement({ path: path });
  }.bind(this));
}

oModel.metadataLoaded(true)          // true: reject if the metadata cannot be loaded
  .then(() => this.setupView())
  .catch(() => this.showServiceUnavailable());

const metaModel = this.getView().getModel().getMetaModel();

metaModel.loaded().then(function () {
  const entityType = metaModel.getODataEntityType("ZPRODUCTS_SRV.Product");
  const priceProperty = metaModel.getODataProperty(entityType, "Price");
  const updatable = priceProperty["sap:updatable"] !== "false";
  this.byId("priceInput").setEditable(updatable);
}.bind(this));

onNavBack: function () {
  const model = this.getView().getModel();
  if (model.hasPendingChanges()) {
    MessageBox.confirm("Discard your changes?", {
      onClose: function (action) {
        if (action === MessageBox.Action.OK) {
          model.resetChanges();
          window.history.go(-1);
        }
      }
    });
  } else {
    window.history.go(-1);
  }
}

